package com.ruoyi.ai.agent;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import junit.framework.TestCase;
import java.lang.reflect.*;
import java.util.*;
import static com.ruoyi.ai.agent.AgentJson.*;

/** Actual existing isolated MySQL, no migration permitted in this suite. */
public class B3LifecycleTest extends TestCase {
    private A1TestFixture f;private ControlledWriteService service;
    protected void setUp()throws Exception{assertTrue("B3 forbids migration",Boolean.getBoolean("a1.schema.prepared"));f=new A1TestFixture();service=new ControlledWriteService(new AgentStore(f.db),f.guard,f.workbooks,f.versions,f.tx.getTransactionManager());A1TestFixture.inject(service,"enabled",true);A1TestFixture.inject(f.runs,"controlled",service);A1TestFixture.inject(f.guard,"enabled",true);A1TestFixture.inject(f.runs,"timeoutMs",900000L);A1TestFixture.inject(f.runs,"businessTools",true);}
    private ObjectNode request(){long w=f.seed("{\"id\":\"b3\",\"sheetOrder\":[\"s\"],\"sheets\":{\"s\":{\"id\":\"s\",\"name\":\"Orders\",\"rowCount\":20,\"columnCount\":10,\"cellData\":{}}}}");ObjectNode ws=f.runs.workspace(w,1),r=obj().put("requestId",UUID.randomUUID().toString()).put("workbookId",w).put("branchId",ws.path("branchId").asLong()).put("loadedRevision",ws.path("loadedRevision").asText()).put("expectedRevision",ws.path("revision").asText()).put("expectedDraftVersion",-1).put("expectedBranchVersion",0).put("activeSheetId","s").put("overwrite","empty-only").put("goal","write");r.set("writeScopes",parse("[{\"sheetId\":\"s\",\"range\":\"B2:C3\"}]"));r.set("actions",parse("[{\"type\":\"setCell\",\"sheetId\":\"s\",\"range\":\"B2\",\"value\":11}]"));return r;}
    private ObjectNode claim(ObjectNode run){return service.claim(run.path("runId").asText(),1,obj().put("clientId","b3").put("fencingToken",run.path("fencingToken").asLong()));}
    private ObjectNode receipt(ObjectNode m){ObjectNode q=obj().put("transportVersion",2).put("callId",m.path("callId").asText()).put("claimToken",m.path("claimToken").asText()).put("argsHash",m.path("argsHash").asText()).put("fencingToken",m.path("fencingToken").asLong()).put("ok",true);ArrayNode cells=arr();for(JsonNode c:m.path("cells")){ObjectNode v=c.deepCopy();v.remove("before");v.put("formula","");cells.add(v);}q.set("cells",cells);return q;}
    private void mutate(ObjectNode run,java.util.function.Consumer<ObjectNode> fn){f.tx.execute(tx->{AgentStore s=new AgentStore(f.db);ObjectNode r=s.locked(run.path("runId").asText());fn.accept(r);s.save(r);return null;});}
    private ObjectNode resolve(ObjectNode req,String kind,long user){try{return(ObjectNode)AgentRunService.class.getMethod("resolveCreation",ObjectNode.class,long.class).invoke(f.runs,obj().put("kind",kind).set("request",req),user);}catch(InvocationTargetException e){if(e.getCause() instanceof RuntimeException)throw(RuntimeException)e.getCause();throw new AssertionError(e);}catch(Exception e){throw new AssertionError("Missing reliable creation lookup",e);}}
    private void reject(Runnable fn){try{fn.run();fail("Unsafe operation accepted");}catch(IllegalArgumentException expected){assertNotNull(expected.getMessage());}}
    public void testUnsupportedPlanCannotDispatchEvenItsFirstRead()throws Exception{
        ObjectNode q=request(),r=f.runs.create(q,1);String id=r.path("runId").asText();
        ObjectNode p=(ObjectNode)parse("{\"steps\":[{\"stepId\":\"R\",\"tool\":\"read_range\",\"dependsOn\":[],\"inputBindings\":{\"sheetId\":\"s\",\"range\":\"A1:B2\"},\"verificationRules\":[{\"type\":\"tool_success\"}]},{\"stepId\":\"W\",\"tool\":\"write_result\",\"dependsOn\":[\"R\"],\"inputBindings\":{\"dataset\":{\"$step\":\"R\"},\"sheetId\":\"s\",\"range\":\"B2\"},\"verificationRules\":[{\"type\":\"tool_success\"}]},{\"stepId\":\"V\",\"tool\":\"verify_result\",\"dependsOn\":[\"W\"],\"inputBindings\":{\"write\":{\"$step\":\"W\"},\"sheetId\":\"s\",\"range\":\"B2\",\"kind\":\"non_empty\"},\"verificationRules\":[{\"type\":\"tool_success\"}]}],\"acceptanceCriteria\":[{\"type\":\"step_succeeded\",\"stepId\":\"R\"},{\"type\":\"step_succeeded\",\"stepId\":\"W\"},{\"type\":\"step_succeeded\",\"stepId\":\"V\"}]}");
        mutate(r,x->{x.set("plan",p);x.put("status","EXECUTING").put("stepIndex",0).put("planVersion",1);});
        Method advance=AgentRunService.class.getDeclaredMethod("advance",ObjectNode.class);advance.setAccessible(true);
        reject(()->f.tx.execute(tx->{AgentStore store=new AgentStore(f.db);ObjectNode state=store.locked(id);try{advance.invoke(f.runs,state);}catch(InvocationTargetException e){throw(IllegalArgumentException)e.getCause();}catch(Exception e){throw new AssertionError(e);}store.save(state);return null;}));
        assertEquals(0,f.db.queryForObject("select count(*) from ai_agent_tool_call where run_id=?",Integer.class,id).intValue());assertEquals(0,f.db.queryForObject("select count(*) from ai_analysis_artifact where run_id=?",Integer.class,id).intValue());assertEquals(0,f.runs.get(id,1).path("outputs").size());assertNull(f.status(q.path("workbookId").asLong()).get("workingState"));
    }
    private void scanUntil(ObjectNode run,String status){int pages=f.db.queryForObject("select count(*) from ai_agent_run",Integer.class)/20+3;for(int i=0;i<pages;i++){f.runs.tick();if(status.equals(f.runs.get(run.path("runId").asText(),1).path("status").asText()))return;}fail("Scheduler did not reconcile target within a complete bounded scan");}
    public void testExactCreationLookupBothEntriesAndNoDuplicate()throws Exception{for(String kind:Arrays.asList("CONTROLLED_WRITE","PLAN_AGENT")){ObjectNode q=request(),r="CONTROLLED_WRITE".equals(kind)?service.create(q,1):f.runs.create(q,1);ObjectNode found=resolve(q,kind,1);assertTrue(found.path("creationVerified").asBoolean());assertEquals(r.path("runId"),found.path("run").path("runId"));ObjectNode duplicate="CONTROLLED_WRITE".equals(kind)?service.create(q,1):f.runs.create(q,1);assertEquals(r.path("runId"),duplicate.path("runId"));assertEquals(1,f.db.queryForObject("select count(*) from ai_agent_run where user_id=1 and request_id=?",Integer.class,q.path("requestId").asText()).intValue());}}
    public void testLookupEmptyIsExplicitlyUnresolved(){ObjectNode q=request(),found=resolve(q,"PLAN_AGENT",1);assertEquals("UNRESOLVED",found.path("status").asText());assertFalse(found.path("creationVerified").asBoolean());assertFalse(found.has("run"));}
    public void testRejectedAdmissionRetainsModelUsageAndOutputs()throws Exception{
        ObjectNode q=request(),r=f.runs.create(q,1);String id=r.path("runId").asText();mutate(r,x->{x.put("status","PLANNING").put("planningToken","b3-pending").put("modelCalls",1);((ObjectNode)x.path("outputs")).put("keep","prior-read");});ObjectNode job=new AgentStore(f.db).get(id);
        A1TestFixture.inject(f.runs,"contextLimit",24000);A1TestFixture.inject(f.runs,"tokenLimit",60000);
        A1TestFixture.inject(f.runs,"llm",new com.ruoyi.ai.service.LlmClient(){public com.ruoyi.ai.service.LlmResponse chat(List<Map<String,String>> m){com.ruoyi.ai.service.LlmResponse out=new com.ruoyi.ai.service.LlmResponse();out.setTotalTokens(9);out.setContent("{\"steps\":[{\"tool\":\"write_result\"}]}");return out;}});
        Method plan=AgentRunService.class.getDeclaredMethod("plan",ObjectNode.class,long.class);plan.setAccessible(true);plan.invoke(f.runs,job,1L);ObjectNode after=f.runs.get(id,1);assertEquals("PAUSED",after.path("status").asText());assertEquals(9,after.path("tokens").asInt());assertEquals("prior-read",after.path("outputs").path("keep").asText());assertEquals(0,f.db.queryForObject("select count(*) from ai_agent_tool_call where run_id=?",Integer.class,id).intValue());
    }
    public void testOlderActiveTaskCannotResolveDifferentRequest(){ObjectNode q=request();service.create(q,1);ObjectNode other=q.deepCopy().put("requestId",UUID.randomUUID().toString());ObjectNode result=resolve(other,"CONTROLLED_WRITE",1);assertEquals("UNRESOLVED",result.path("status").asText());assertFalse(result.has("run"));}
    public void testInvalidDeclaredTransportCreatesNoRunOrLease(){for(boolean direct:Arrays.asList(true,false)){ObjectNode q=request().put("transportVersion",1);reject(()->{if(direct)service.create(q,1);else f.runs.create(q,1);});assertEquals(0,f.db.queryForObject("select count(*) from ai_agent_run where workbook_id=?",Integer.class,q.path("workbookId").asLong()).intValue());assertEquals(0,f.db.queryForObject("select count(*) from ai_agent_lease where workbook_id=? and run_id is not null",Integer.class,q.path("workbookId").asLong()).intValue());}}
    public void testValidLegacySnapshotIdentitiesStillBlockedWithUnchangedVersion(){
        ObjectNode q=request();long w=q.path("workbookId").asLong();ObjectNode before=f.runs.workspace(w,1);String id=UUID.randomUUID().toString();
        ObjectNode r=obj().put("runId",id).put("userId",1).put("workbookId",w).put("branchId",q.path("branchId").asLong()).put("status","EXECUTING").put("version",0).put("eventSeq",0).put("fencingToken",1).put("revision",before.path("revision").asText());
        ObjectNode call=obj().put("callId","legacy").put("status","CLAIMED").put("claimToken","real-legacy-token").put("argsHash","legacy-args");r.set("call",call);
        f.db.update("insert into ai_agent_run values(?,?,?,?,?,?,'EXECUTING',?,0,now(3),now(3))",id,1,w,q.path("branchId").asLong(),UUID.randomUUID().toString(),hash(r),r.toString());new AgentStore(f.db).call(r,call);f.db.update("insert into ai_agent_lease values(?,?,1,?)",w,id,System.currentTimeMillis()+120000);
        try{f.runs.claim(id,1,obj().put("clientId","legacy-client").put("fencingToken",1));fail("Old claim allowed");}catch(IllegalArgumentException e){assertTrue(e.getMessage().contains("SNAPSHOT_WRITE_BLOCKED"));}
        ObjectNode receipt=obj().put("callId","legacy").put("claimToken","real-legacy-token").put("argsHash","legacy-args").put("fencingToken",1).put("ok",true).put("calculationVerified",true);receipt.set("snapshot",obj().put("tampered",true));
        try{f.runs.receipt(id,1,receipt);fail("Old receipt allowed");}catch(IllegalArgumentException e){assertTrue(e.getMessage().contains("SNAPSHOT_WRITE_BLOCKED"));}
        assertEquals(before,f.runs.workspace(w,1));assertEquals("CLAIMED",f.db.queryForObject("select status from ai_agent_tool_call where run_id=?",String.class,id));
    }
    public void testLookupRejectsForgedRequestAndOtherOwner(){ObjectNode q=request();service.create(q,1);ObjectNode wrong=q.deepCopy().put("goal","changed");reject(()->resolve(wrong,"CONTROLLED_WRITE",1));reject(()->resolve(q,"CONTROLLED_WRITE",2));}
    public void testLookupSurvivesDisabledEntrypoints()throws Exception{ObjectNode q=request(),r=service.create(q,1);A1TestFixture.inject(service,"enabled",false);A1TestFixture.inject(f.guard,"enabled",false);assertEquals(r.path("runId"),resolve(q,"CONTROLLED_WRITE",1).path("run").path("runId"));}
    public void testUnclaimedDeadlineStopsAndDoesNotWrite()throws Exception{ObjectNode q=request(),r=service.create(q,1);mutate(r,x->x.put("deadline",1));A1TestFixture.inject(f.guard,"enabled",false);scanUntil(r,"FAILED");ObjectNode current=f.runs.get(r.path("runId").asText(),1);assertEquals("FAILED",current.path("status").asText());assertNull(f.status(q.path("workbookId").asLong()).get("workingState"));reject(()->claim(r));}
    public void testClaimedDeadlineBecomesUnknownEvenWhenDisabled()throws Exception{ObjectNode q=request(),r=service.create(q,1),m=claim(r);mutate(r,x->x.put("deadline",1));A1TestFixture.inject(f.guard,"enabled",false);scanUntil(r,"PAUSED");ObjectNode paused=f.runs.get(r.path("runId").asText(),1);assertEquals("PAUSED",paused.path("status").asText());assertEquals("UNKNOWN",paused.path("call").path("status").asText());assertTrue(paused.path("fencingToken").asLong()>r.path("fencingToken").asLong());reject(()->service.receipt(r.path("runId").asText(),1,receipt(m)));assertNull(f.status(q.path("workbookId").asLong()).get("workingState"));}
    public void testExpiredLeaseRejectsLateSuccessAndKeepsLeaseOwner(){ObjectNode q=request(),r=service.create(q,1),m=claim(r);f.db.update("update ai_agent_lease set expires_at=1 where run_id=?",r.path("runId").asText());scanUntil(r,"PAUSED");ObjectNode paused=f.runs.get(r.path("runId").asText(),1);assertEquals("UNKNOWN",paused.path("call").path("status").asText());assertEquals(1,f.db.queryForObject("select count(*) from ai_agent_lease where run_id=?",Integer.class,r.path("runId").asText()).intValue());reject(()->service.receipt(r.path("runId").asText(),1,receipt(m)));}
    public void testCancelClaimedPreventsLateSuccessThenReconcileStops(){ObjectNode q=request(),r=service.create(q,1),m=claim(r);f.runs.cancel(r.path("runId").asText(),1);reject(()->service.receipt(r.path("runId").asText(),1,receipt(m)));ObjectNode ws=f.runs.workspace(q.path("workbookId").asLong(),1);ObjectNode ended=f.runs.resume(r.path("runId").asText(),1,obj().put("reloadedServerDraft",true).put("expectedRevision",ws.path("revision").asText()));assertEquals("CANCELLED",ended.path("status").asText());assertNull(f.status(q.path("workbookId").asLong()).get("workingState"));}
    public void testSavedReceiptAfterDeadlineIsReadOnlyIdempotent(){ObjectNode q=request(),r=service.create(q,1),m=claim(r),ok=receipt(m);service.receipt(r.path("runId").asText(),1,ok);mutate(r,x->x.put("deadline",1));assertEquals("COMPLETED",service.receipt(r.path("runId").asText(),1,ok).path("status").asText());f.runs.cancel(r.path("runId").asText(),1);assertEquals(0,((Number)((Map<?,?>)f.status(q.path("workbookId").asLong()).get("workingState")).get("version")).intValue());}
}
